	cluster.NumConns = 1
	db, err := cluster.open()
	if err != nil {
		b.Fatalf("newClusterSettings: %v", err)
	}
	defer db.Close()

	b.ResetTimer()
	b.RunParallel(func(pb *testing.PB) {
		for pb.Next() {
			err := execTestStatement(context.Background(), db, "void", Options{})
			if err != nil {
				b.Error(err)
				return
			}
		}
	})
}

