func TestPrepareBatchMetadataMultipleKeyspaceTables(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	srv := NewTestServer(t, protoVersion4, ctx)
	defer srv.Stop()

	cfg := testCluster(protoVersion4, srv.Address)
